export async function listTools() {
  return [
    {
      name: 'order_status',
      description: 'Get the current status of an order, optionally including its chronological history.',
      inputSchema: {
        type: 'object',
        properties: {
          order_id: { type: 'string', description: 'The order identifier.' },
          include_history: { type: 'boolean', description: 'Whether to include the chronological status history. Defaults to false.' }
        },
        required: ['order_id'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'order_status') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const arguments_ = args || {};
  if (typeof arguments_ !== 'object' || Array.isArray(arguments_) || arguments_ === null) {
    throw new Error('Arguments must be an object');
  }

  const allowed = new Set(['order_id', 'include_history']);
  for (const key of Object.keys(arguments_)) {
    if (!allowed.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  if (!('order_id' in arguments_)) {
    throw new Error('Missing required field: order_id');
  }
  const orderId = arguments_.order_id;
  if (typeof orderId !== 'string') {
    throw new Error('order_id must be a string');
  }

  let includeHistory = false;
  if ('include_history' in arguments_) {
    if (typeof arguments_.include_history !== 'boolean') {
      throw new Error('include_history must be a boolean');
    }
    includeHistory = arguments_.include_history;
  }

  if (!(orderId in orders)) {
    throw new Error(`Order not found: ${orderId}`);
  }

  const order = orders[orderId];
  const lines = [`Order ${orderId} status: ${order.status}`];
  if (includeHistory && Array.isArray(order.history)) {
    lines.push(`History: ${order.history.join(', ')}`);
  }

  return {
    content: [{ type: 'text', text: lines.join('\n') }]
  };
}
```

